-- The two checklists published on 2026-11-09: The Months Before a Baby
-- Arrives (Pregnancy) and The Anniversary of a Death (Anniversaries).
-- Generated by `python3 tools/checklists_sql.py the-months-before-a-baby-arrives
-- the-anniversary-of-a-death`; the repo copy in data/checklists.json is the
-- source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('the-months-before-a-baby-arrives', 'The Months Before a Baby Arrives', 'For the months before a baby comes, when advice arrives faster than answers. It gets your questions written down for short appointments, settles who is told what, packs the bag early, and checks what your leave and pay actually are.', 'Pregnancy', '["Write your questions down as they occur to you — appointments are short and memory is worse than you think.", "Decide together who gets told what, and when — one agreed answer saves repeating yourself all month.", "Say the frightening thought out loud to one person — unspoken fear gets very loud at night.", "Pack the bag four weeks before you think you need to — early is calm and late is frantic.", "Work out what the first two weeks at home need — meals, a sleeping plan, who comes and when.", "Ask what your leave and pay actually are, in writing — assumptions here turn out expensive.", "Keep one thing that is entirely yours — a baby takes the calendar, not the whole person.", "Tell your midwife or doctor about low mood now — the weeks before count, not only the weeks after.", "Let the birth plan be a preference, not a promise — the day rarely reads the document."]'::jsonb, 'weekly', array['Parenting', 'Body', 'Life Transitions']::text[], 1, '2026-11-09T16:00:00+00:00'::timestamptz),
  ('the-anniversary-of-a-death', 'The Anniversary of a Death', 'For the anniversary of losing someone, and the days leading up to it. It decides in advance how the day will go, tells one person the date, makes room for something that was theirs, and plans a landing for the morning after.', 'Anniversaries', '["Decide in advance how you want the day to go — a day you planned is easier than one that arrives.", "Tell one person what the date is — being quietly held in mind costs them nothing.", "Take the day off if you can, or the afternoon — grief keeps its own calendar and this is on it.", "Do one thing that was theirs — a recipe, a walk, a record they wore out.", "Let the day be smaller or bigger than you feared — the run-up is often worse than the date itself.", "Write them a few lines you will not send — saying it somewhere is different from saying nothing.", "Keep 988 in your phone for the hard hours — call or text, any time, free across the United States.", "Eat something and drink water even if nothing appeals — a grieving body still has to be carried.", "Plan something ordinary for the next morning — the day after an anniversary needs a landing."]'::jsonb, 'as needed', array['Grief', 'Loss', 'Self-Compassion']::text[], 1, '2026-11-09T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
